// Trailing-slash guard and 404 page generated by prerender.mjs. No build needed.
import assert from 'node:assert/strict';
import {test} from 'node:test';

const saved = process.env.SITE_URL;
delete process.env.SITE_URL;
const {slashGuard, homeHref, notFoundDocument} = await import('../prerender.mjs');
const script = slashGuard.match(/^<script>([\s\S]*)<\/script>$/)[1];

function redirect(pathname) {
  let replaced;
  const location = {pathname, search: '?q=1', hash: '#h', replace(value) { replaced = value; }};
  new Function('location', script)(location);
  return replaced;
}
function withSite(value, run) {
  if (value === undefined) delete process.env.SITE_URL; else process.env.SITE_URL = value;
  try { run(); } finally {
    if (saved === undefined) delete process.env.SITE_URL; else process.env.SITE_URL = saved;
  }
}

test('slash guard redirects to the directory URL', () => {
  assert.equal(redirect('/tools/x/index.html'), '/tools/x/?q=1#h', 'index.html directory');
  assert.equal(redirect('/tools/x'), '/tools/x/?q=1#h', 'missing slash');
  assert.equal(redirect('/tools/x/'), undefined, 'already slashed');
  assert.equal(redirect('/index.html'), '/?q=1#h', 'root index');
  assert.equal(redirect('/pdf/tools/x/index.html'), '/pdf/tools/x/?q=1#h', 'subdirectory index');
});

test('home link and 404 page follow SITE_URL', () => {
  withSite(undefined, () => {
    assert.equal(homeHref(), '/', 'home default');
    assert.equal(notFoundDocument().includes('href="/"'), true, '404 default');
  });
  withSite('https://example.com/pdf', () => {
    assert.equal(homeHref(), '/pdf/', 'home from SITE_URL');
    assert.equal(notFoundDocument().includes('href="/pdf/"'), true, '404 base path');
  });
  withSite('https://example.com/pdf/', () => {
    assert.equal(homeHref(), '/pdf/', 'home keeps slash');
  });
});
